/*
 * This inbox sits inside OpsShell, which already consumes 238px for its sidebar and
 * 60px for workspace padding.  The former 1320px viewport breakpoint therefore
 * left only ~1140px for a 1360px four-column inbox at a common 1440px desktop
 * viewport.  The shell hid the overflow, clipping every control in the inspector.
 * Collapse before the *inner* workspace becomes narrower than the inbox instead.
 */
@media(max-width:1600px){.shell{grid-template-columns:72px 300px minmax(420px,1fr)}.rail .brand div,.navItem span:first-child,.connection,.operator{display:none}.rail{padding:16px 9px}.inspector{grid-column:2/4;border-top:1px solid var(--staff-line, var(--ui-canvas));display:grid;grid-template-columns:repeat(3,1fr);gap:10px;max-height:none}.card{margin:0}}
@media(max-width:900px){.shell{grid-template-columns:1fr}.rail{display:none}.list{border-right:0}.chat{min-height:650px}.inspector{grid-column:auto;display:block}.bubble{max-width:88%}}

.noteInput{width:100%;min-height:90px;border:1px solid var(--staff-line, #d7dee8);border-radius:calc(10px * var(--paw-radius-scale));padding:10px;margin-bottom:8px;resize:vertical;font:inherit}.note{border-bottom:1px solid var(--staff-line, var(--ui-canvas));padding:10px 0}.note p{white-space:pre-wrap;overflow-wrap:anywhere;margin:6px 0}

/* Fit the available staff workspace; every inspector action remains in document flow. */
.shell { min-width:0; }
.list,.chat,.inspector,.card,.person,.person>div { min-width:0; }
.kv { grid-template-columns:minmax(80px,.65fr) minmax(0,1fr); }
.kv b,.kv span,.row small,.auditItem span { overflow-wrap:anywhere; }
.chatHead,.aiBar { flex-wrap:wrap; }
.composer { flex-wrap:wrap; }
.composer input { min-width:0; flex:1 1 180px; }
.listTop select { width:100%; margin-top:6px; }
.list>.filters { padding:10px 14px; }
.actions { grid-template-columns:repeat(2,minmax(0,1fr)); }
.action,.send { white-space:normal; }
@media(max-width:1200px) { .shell { grid-template-columns:64px minmax(220px,.85fr) minmax(0,1.4fr); } .inspector { grid-template-columns:repeat(2,minmax(0,1fr)); } }
@media(max-width:900px) { .shell { grid-template-columns:minmax(0,1fr); } .inspector { grid-column:auto; } }
@media(max-width:480px) { .chatHead,.messages,.composer { padding:14px; } .cardHead { flex-wrap:wrap; } .bubble { max-width:95%; } }
/* Do not make an enabled Send action look disabled; its original disabled gate is unchanged. */
.send:not(:disabled) { opacity:1; background:var(--staff-primary); color:var(--staff-on-primary); }
/* ---------------------------------------------------------------------------------------------------
 * WATI look for the shared inbox: the WhatsApp beige patterned conversation, customer messages in white
 * on the left and PawSpace (bot, AI, team) in WhatsApp green on the right with bubble tails and grey
 * timestamps, WATI-style list rows with a green selection bar, and a pill composer with a green Send.
 * --------------------------------------------------------------------------------------------------- */
.shell{--wa-canvas:#efeae2;--wa-dots:#d8d2c7;--wa-in:#ffffff;--wa-out:#d9fdd3;--wa-text:#111b21;--wa-meta:#667781;--wa-accent:#00a884;--wa-head:#f0f2f5;--wa-line:#e9edef;--wa-panel:#ffffff;--wa-hover:#f5f6f6;--wa-avatar:#dfe5e7;--wa-avatar-text:#54656f;--wa-chip-line:#d1d7db;--wa-chip-on:#e7fce3;--wa-chip-on-text:#008069;--wa-chip-on-line:#b6e7c3}
:global(html[data-paw-mode="dark"]) .shell{--wa-canvas:#0b141a;--wa-dots:#1c272d;--wa-in:#202c33;--wa-out:#005c4b;--wa-text:#e9edef;--wa-meta:#8696a0;--wa-accent:#00a884;--wa-head:#202c33;--wa-line:#2a3942;--wa-panel:#111b21;--wa-hover:#202c33;--wa-avatar:#2a3942;--wa-avatar-text:#aebac1;--wa-chip-line:#2a3942;--wa-chip-on:#0a332c;--wa-chip-on-text:#00d7a5;--wa-chip-on-line:#005c4b}
.chat{background:var(--wa-canvas)}
.chatHead{background:var(--wa-head);border-bottom-color:var(--wa-line)}
.avatar{background:var(--wa-avatar);color:var(--wa-avatar-text)}
.messages{background-color:var(--wa-canvas);background-image:radial-gradient(var(--wa-dots) 1px,transparent 1px),radial-gradient(var(--wa-dots) 1px,transparent 1px);background-size:26px 26px;background-position:0 0,13px 13px;gap:8px}
.bubble{position:relative;border:0;border-radius:calc(8px * var(--paw-radius-scale));border-top-left-radius:0;background:var(--wa-in);color:var(--wa-text);box-shadow:0 1px .5px rgba(11,20,26,.13);padding:7px 11px 6px}
.bubble::before{content:"";position:absolute;top:0;left:-8px;border-right:8px solid var(--wa-in);border-bottom:10px solid transparent}
.bubbleOut{background:var(--wa-out);border-top-left-radius:8px;border-top-right-radius:0}
.bubbleOut::before{left:auto;right:-8px;border-right:0;border-left:8px solid var(--wa-out)}
.bubble small{color:var(--wa-meta);font-size:13px}
.bubble p{color:var(--wa-text)}
.composer{background:var(--wa-head);border-top:0}
.composer input{border:0;border-radius:calc(24px * var(--paw-radius-scale));background:var(--wa-panel);color:var(--wa-text);padding:11px 18px}
.send:not(:disabled){background:var(--wa-accent);color:#fff}
.aiBar{background:var(--wa-panel);border-color:var(--wa-line)}
.list{background:var(--wa-panel)}
.row{border-bottom-color:var(--wa-head);border-left:3px solid transparent}
.row:hover{background:var(--wa-hover)}
.row[aria-current="true"]{background:var(--wa-head);border-left-color:var(--wa-accent)}
.filter{border-color:var(--wa-chip-line);color:var(--wa-avatar-text)}
.filterActive{background:var(--wa-chip-on);color:var(--wa-chip-on-text);border-color:var(--wa-chip-on-line)}
