/*
 * This inbox sits inside OpsShell, which already consumes 238px for its sidebar and
 * 60px for workspace padding.  The former 1320px viewport breakpoint therefore
 * left only ~1140px for a 1360px four-column inbox at a common 1440px desktop
 * viewport.  The shell hid the overflow, clipping every control in the inspector.
 * Collapse before the *inner* workspace becomes narrower than the inbox instead.
 */
@media(max-width:1600px){.shell{grid-template-columns:72px 300px minmax(420px,1fr)}.rail .brand div,.navItem span:first-child,.connection,.operator{display:none}.rail{padding:16px 9px}.inspector{grid-column:2/4;border-top:1px solid var(--staff-line, var(--ui-canvas));display:grid;grid-template-columns:repeat(3,1fr);gap:10px;max-height:none}.card{margin:0}}
@media(max-width:900px){.shell{grid-template-columns:1fr}.rail{display:none}.list{border-right:0}.chat{min-height:650px}.inspector{grid-column:auto;display:block}.bubble{max-width:88%}}

.noteInput{width:100%;min-height:90px;border:1px solid var(--staff-line, #d7dee8);border-radius:calc(10px * var(--paw-radius-scale));padding:10px;margin-bottom:8px;resize:vertical;font:inherit}.note{border-bottom:1px solid var(--staff-line, var(--ui-canvas));padding:10px 0}.note p{white-space:pre-wrap;overflow-wrap:anywhere;margin:6px 0}

/* Fit the available staff workspace; every inspector action remains in document flow. */
.shell { min-width:0; }
.list,.chat,.inspector,.card,.person,.person>div { min-width:0; }
.kv { grid-template-columns:minmax(80px,.65fr) minmax(0,1fr); }
.kv b,.kv span,.row small,.auditItem span { overflow-wrap:anywhere; }
.chatHead,.aiBar { flex-wrap:wrap; }
.composer { flex-wrap:wrap; }
.composer input { min-width:0; flex:1 1 180px; }
.listTop select { width:100%; margin-top:6px; }
.list>.filters { padding:10px 14px; }
.actions { grid-template-columns:repeat(2,minmax(0,1fr)); }
.action,.send { white-space:normal; }
@media(max-width:1200px) { .shell { grid-template-columns:64px minmax(220px,.85fr) minmax(0,1.4fr); } .inspector { grid-template-columns:repeat(2,minmax(0,1fr)); } }
@media(max-width:900px) { .shell { grid-template-columns:minmax(0,1fr); } .inspector { grid-column:auto; } }
@media(max-width:480px) { .chatHead,.messages,.composer { padding:14px; } .cardHead { flex-wrap:wrap; } .bubble { max-width:95%; } }
