 const existing=await db.prepare("SELECT id,lead_id FROM communication_threads WHERE customer_id=? AND booking_id IS NULL AND ticket_id IS NULL AND status='open' ORDER BY CASE WHEN lead_id IS NOT NULL THEN 0 ELSE 1 END,updated_at DESC LIMIT 1").bind(customerId).first<Row>();if(existing){const threadId=text(existing.id);await db.prepare("UPDATE communication_threads SET lead_id=COALESCE(lead_id,?),assigned_to=COALESCE(?,assigned_to),updated_at=? WHERE id=?").bind(leadId,assignedTo,Date.now(),threadId).run();return threadId;}const now=Date.now(),threadId=`THREAD-${crypto.randomUUID().slice(0,12).toUpperCase()}`;await db.batch([db.prepare("INSERT INTO communication_threads (id,customer_id,booking_id,lead_id,ticket_id,status,assigned_to,sla_due_at,created_at,updated_at) VALUES (?,?,NULL,?,NULL,'open',?,NULL,?,?)").bind(threadId,customerId,leadId,assignedTo,now,now),db.prepare("INSERT OR IGNORE INTO communication_participants (id,thread_id,participant_type,participant_id,display_ref,role,created_at) VALUES (?,?,?,?,?,'customer',?)").bind(crypto.randomUUID(),threadId,"customer",customerId,customerId,now)]);return threadId;}

