s,provider,provider_reference,idempotency_key,policy_json,created_by,created_at,updated_at) VALUES (?,?,?,NULL,?,NULL,'inbound','whatsapp','transactional','whatsapp_uat_inbound',?,'received',?,?,?,?,'whatsapp_uat_webhook',?,?)").bind(messageId,threadId,customerId,leadId,JSON.stringify({text:messageText,...detail}),input.provider,eventId,`whatsapp-uat:${input.provider}:${eventId}`,JSON.stringify(policy),now,now),db.prepare("INSERT INTO whatsapp_uat_events (id,provider,event_id,event_type,payload_hash,customer_id,message_id,thread_id,detail_json,created_at) VALUES (?,?,?,?,?,?,?,?,?,?)").bind(`WAUAT-${crypto.randomUUID().slice(0,12).toUpperCase()}`,input.provider,eventId,"inbound_message",input.payloadHash,customerId,messageId,threadId,JSON.stringify({...detail,leadId}),now),db.prepare("INSERT INTO whatsapp_uat_sessions (customer_id,provider,last_inbound_at,last_outbound_at) VALUES (?,?,?,NULL) ON CONFLICT(customer_id,provider) DO UPDATE SET last_inbound_at=excluded.last_inbound_at").bind(customerId,input.provider,now),db.prepare("UPDATE communication_threads SET updated_at=? WHERE id=?").bind(now,threadId)]);return{duplicatePrevented:false as const,messageId,threadId,customerId,leadId,status:"received",identitySource:identity.identitySource,externalDelivery:false};}

