export async function queueWhatsAppUatOutbound(db:D1Database,input:{provider:WhatsAppUatProvider;threadId:string;customerId:string;text:string;idempotencyKey:string;createdBy:string;templateKey?:string|null;language?:string|null;requestFingerprint?:string;now?:number;
