 const thread=await db.prepare("SELECT id FROM communication_threads WHERE id=? AND customer_id=? AND status='open'").bind(input.threadId,input.customerId).first<Row>();if(!thread)throw new Error("Canonical open conversation thread not found");const messageId=`MSG-WA-${crypto.randomUUID().slice(0,12).toUpperCase()}`,purpose=templateCategory==="marketing"?"marketing":"transactional",policy={environment:"uat",provider:input.provider,externalDelivery:false,sessionWindowHours:24,withinSession,templateKey:key||null,templateCategory,consentVerified:true,marketingConsentVerified:templateCategory==="marketing",...(input.requestFingerprint?{requestFingerprint:input.requestFingerprint}:{})};let statements=[db.prepare("INSERT INTO communication_messages (id,thread_id,customer_id,booking_id,lead_id,ticket_id,direction,channel,purpose,template_key,payload_json,status,provider,provider_reference,idempotency_key,policy_json,created_by,created_at,updated_at) VALUES (?,?,?,NULL,NULL,NULL,'outbound','whatsapp',?,?,?, 'queued',?,NULL,?,?,?, ?,?)").bind(messageId,input.threadId,input.customerId,purpose,key||"whatsapp_session_reply",JSON.stringify({...input.interactive?{text:input.text,interactive:input.interactive}:{text:input.text},...(key?{language:text(input.language)||"en"}:{})}),input.provider,idempotencyKey,JSON.stringify(policy),input.createdBy,now,now),db.prepare("INSERT INTO communication_outbox (message_id,status,next_attempt_at,attempt_count,max_attempts,last_error,locked_at,updated_at) VALUES (?,'queued',?,0,5,NULL,NULL,?)").bind(messageId,now,now),db.prepare("UPDATE whatsapp_uat_sessions SET last_outbound_at=? WHERE customer_id=? AND provider=?").bind(now,input.customerId,input.provider),
