   db.prepare(`INSERT INTO communication_messages (id,thread_id,customer_id,booking_id,lead_id,ticket_id,direction,channel,purpose,template_key,payload_json,status,provider,provider_reference,idempotency_key,policy_json,created_by,created_at,updated_at) SELECT ?,t.id,t.customer_id,NULL,NULL,NULL,'outbound','whatsapp',?,?,?,'queued',?,NULL,?,?,?,?,? FROM communication_threads t WHERE t.id=? AND t.customer_id=? AND t.status='open' AND (${input.commitGuard.sql})`).bind(messageId,purpose,key||"whatsapp_session_reply",JSON.stringify({...input.interactive?{text:input.text,interactive:input.interactive}:{text:input.text},...(key?{language:text(input.language)||"en"}:{})}),input.provider,idempotencyKey,JSON.stringify(policy),input.createdBy,now,now,input.threadId,input.customerId,...input.commitGuard.binds),
   db.prepare(`INSERT INTO communication_outbox (message_id,status,next_attempt_at,attempt_count,max_attempts,last_error,locked_at,updated_at) SELECT ?,'queued',?,0,5,NULL,NULL,? WHERE ${inserted}`).bind(messageId,now,now,...boundMessage),
