export async function recordWhatsAppUatDelivery(db:D1Database,input:{provider:WhatsAppUatProvider;eventId:string;messageId:string;eventType:"accepted"|"sent"|"delivered"|"read"|"failed";payloadHash:string;detail?:Record<string,unknown>}){await ensureWhatsAppUatTables(db);if(!whatsappUatProviders.includes(input.provider))throw new Error("Unsupported WhatsApp UAT provider");const prior=await db.prepare("SELECT * FROM whatsapp_uat_events WHERE provider=? AND event_id=?").bind(input.provider,input.eventId).first<Row>();if(prior)return{duplicatePrevented:true,event:prior,externalDelivery:false};const result=await recordDeliveryEvent(db,{messageId:input.messageId,provider:input.provider,eventId:input.eventId,eventType:input.eventType,detail:{environment:"uat",externalDelivery:false,...(input.detail??{})}}),now=Date.now();await db.prepare("INSERT INTO whatsapp_uat_events (id,provider,event_id,event_type,payload_hash,customer_id,message_id,thread_id,detail_json,created_at) SELECT ?,?,?,?,?,m.customer_id,m.id,m.thread_id,?,? FROM communication_messages m WHERE m.id=?").bind(`WAUAT-${crypto.randomUUID().slice(0,12).toUpperCase()}`,input.provider,input.eventId,`delivery_${input.eventType}`,input.payloadHash,JSON.stringify({environment:"uat",externalDelivery:false,...(input.detail??{})}),now,input.messageId).run();return{...result,staffFallbackRequired:input.eventType==="failed",externalDelivery:false};}

import{ensureConversationGovernance,getConversation}from"./conversation-governance";
