type Db=D1Database;type Row=Record<string,unknown>;const text=(value:unknown)=>String(value??"").trim();const uid=(prefix:string)=>`${prefix}-${crypto.randomUUID().slice(0,12).toUpperCase()}`;
export async function ensureWhatsAppInboxProductivity(db:Db){await ensureConversationGovernance(db);await db.batch([
 db.prepare("CREATE TABLE IF NOT EXISTS whatsapp_quick_replies (id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,label TEXT NOT NULL,body TEXT NOT NULL,variables_json TEXT NOT NULL DEFAULT '[]',approved_media_ref TEXT,active INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,updated_by TEXT NOT NULL,updated_at INTEGER NOT NULL)"),
