 db.prepare("CREATE TABLE IF NOT EXISTS conversation_operator_priority (thread_id TEXT NOT NULL,actor_email TEXT NOT NULL,unread INTEGER NOT NULL DEFAULT 0,favourite INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL,PRIMARY KEY(thread_id,actor_email))"),
]);}
const variableNames=(body:string)=>[...body.matchAll(/\{\{([a-zA-Z][a-zA-Z0-9_]*)\}\}/g)].map(match=>match[1]);
export async function saveWhatsAppQuickReply(db:Db,input:{code:string;label:string;body:string;approvedMediaRef?:string|null;actorEmail:string}){await ensureWhatsAppInboxProductivity(db);const code=text(input.code).toLowerCase(),label=text(input.label),body=text(input.body);if(!/^[a-z0-9_]{3,64}$/.test(code)||label.length<2||body.length<1||body.length>2000)throw new Response("Valid quick-reply code, label and body are required",{status:400});const variables=[...new Set(variableNames(body))];const media=text(input.approvedMediaRef);if(media&&!/^MEDIA-[A-Z0-9_-]{4,120}$/i.test(media))throw new Response("Quick-reply media must reference an approved PawSpace media asset",{status:400});const now=Date.now();await db.prepare("INSERT INTO whatsapp_quick_replies (id,code,label,body,variables_json,approved_media_ref,active,created_by,created_at,updated_by,updated_at) VALUES (?,?,?,?,?,?,1,?,?,?,?) ON CONFLICT(code) DO UPDATE SET label=excluded.label,body=excluded.body,variables_json=excluded.variables_json,approved_media_ref=excluded.approved_media_ref,active=1,updated_by=excluded.updated_by,updated_at=excluded.updated_at").bind(uid("WQR"),code,label,body,JSON.stringify(variables),media||null,input.actorEmail,now,input.actorEmail,now).run();return{code,label,body,variables,approvedMediaRef:media||null};}
export async function renderWhatsAppQuickReply(db:Db,input:{code:string;values:Record<string,string>}){await ensureWhatsAppInboxProductivity(db);const row=await db.prepare("SELECT * FROM whatsapp_quick_replies WHERE code=? AND active=1").bind(text(input.code).toLowerCase()).first<Row>();if(!row)throw new Response("Active quick reply not found",{status:404});const variables=JSON.parse(text(row.variables_json)||"[]") as string[],provided=Object.keys(input.values||{});if(variables.some(name=>!text(input.values[name]))||provided.some(name=>!variables.includes(name)))throw new Response("Quick-reply variables must match the approved contract exactly",{status:400});let body=text(row.body);for(const name of variables)body=body.replaceAll(`{{${name}}}`,text(input.values[name]));if(/\{\{[^}]+\}\}/.test(body))throw new Response("Unresolved quick-reply variable",{status:409});return{code:text(row.code),body,approvedMediaRef:text(row.approved_media_ref)||null,governed:true};}
export async function setConversationTag(db:Db,input:{threadId:string;code:string;label?:string;actorEmail:string;attached:boolean}){await ensureWhatsAppInboxProductivity(db);const thread=await db.prepare("SELECT id FROM communication_threads WHERE id=?").bind(input.threadId).first<Row>();if(!thread)throw new Response("Conversation not found",{status:404});const code=text(input.code).toLowerCase();if(!/^[a-z0-9_:-]{2,64}$/.test(code))throw new Response("Valid operational tag code is required",{status:400});let tag=await db.prepare("SELECT id FROM conversation_tags WHERE code=?").bind(code).first<Row>();if(!tag){const id=uid("CTAG");await db.prepare("INSERT INTO conversation_tags (id,code,label,created_by,created_at) VALUES (?,?,?,?,?)").bind(id,code,text(input.label)||code,input.actorEmail,Date.now()).run();tag={id};}if(input.attached)await db.prepare("INSERT OR IGNORE INTO conversation_thread_tags (thread_id,tag_id,created_by,created_at) VALUES (?,?,?,?)").bind(input.threadId,tag.id,input.actorEmail,Date.now()).run();else await db.prepare("DELETE FROM conversation_thread_tags WHERE thread_id=? AND tag_id=?").bind(input.threadId,tag.id).run();return{threadId:input.threadId,code,attached:input.attached};}
export async function setConversationPriority(db:Db,input:{threadId:string;actorEmail:string;unread?:boolean;favourite?:boolean}){await ensureWhatsAppInboxProductivity(db);const current=await db.prepare("SELECT unread,favourite FROM conversation_operator_priority WHERE thread_id=? AND actor_email=?").bind(input.threadId,input.actorEmail).first<Row>(),unread=input.unread??Number(current?.unread||0)===1,favourite=input.favourite??Number(current?.favourite||0)===1;await db.prepare("INSERT INTO conversation_operator_priority (thread_id,actor_email,unread,favourite,updated_at) VALUES (?,?,?,?,?) ON CONFLICT(thread_id,actor_email) DO UPDATE SET unread=excluded.unread,favourite=excluded.favourite,updated_at=excluded.updated_at").bind(input.threadId,input.actorEmail,unread?1:0,favourite?1:0,Date.now()).run();return{threadId:input.threadId,unread,favourite};}
export async function searchWhatsAppInbox(db:Db,input:{actor:ConversationAccessActor;actorEmail:string;query?:string;owner?:string;status?:string;tag?:string;channel?:string;unread?:boolean;favourite?:boolean;limit?:number}){await ensureWhatsAppInboxProductivity(db);await ensureConversationAccessTables(db);const access=conversationAccessPredicate(input.actor,"t"),where=[access.sql],binds:unknown[]=[...access.binds];if(text(input.owner)){where.push("COALESCE(t.assigned_to,'')=?");binds.push(text(input.owner));}if(text(input.status)){where.push("t.status=?");binds.push(text(input.status));}if(text(input.tag)){where.push("EXISTS (SELECT 1 FROM conversation_thread_tags tt JOIN conversation_tags tg ON tg.id=tt.tag_id WHERE tt.thread_id=t.id AND tg.code=?)");binds.push(text(input.tag).toLowerCase());}if(text(input.channel)){where.push("EXISTS (SELECT 1 FROM communication_messages cm WHERE cm.thread_id=t.id AND cm.channel=?)");binds.push(text(input.channel));}if(text(input.query)){where.push("(lower(t.id) LIKE ? OR lower(COALESCE(t.customer_id,'')) LIKE ? OR lower(COALESCE(t.lead_id,'')) LIKE ? OR lower(COALESCE(t.booking_id,'')) LIKE ?)");const q=`%${text(input.query).toLowerCase()}%`;binds.push(q,q,q,q);}if(input.unread!==undefined){where.push("COALESCE(p.unread,0)=?");binds.push(input.unread?1:0);}if(input.favourite!==undefined){where.push("COALESCE(p.favourite,0)=?");binds.push(input.favourite?1:0);}const limit=Math.min(200,Math.max(1,input.limit||100));const rows=await db.prepare(`SELECT t.*,COALESCE(p.unread,0) unread,COALESCE(p.favourite,0) favourite FROM communication_threads t LEFT JOIN conversation_operator_priority p ON p.thread_id=t.id AND p.actor_email=? WHERE ${where.join(" AND ")} ORDER BY t.updated_at DESC LIMIT ?`).bind(input.actorEmail,...binds,limit).all<Row>();return{threads:rows.results,canonicalOwnership:true};}
export async function buildGovernedConversationTranscript(db:Db,input:{threadId:string;maskSensitive:boolean;actorEmail:string}){await ensureWhatsAppInboxProductivity(db);const conversation=await getConversation(db,input.threadId,"staff");if(!conversation)throw new Response("Conversation not found",{status:404});const messages=(conversation.messages as Array<Record<string,unknown>>).map(message=>{const payload={...(message.payload as Record<string,unknown>||{})};if(input.maskSensitive){for(const key of ["customerPhone","providerPhone","phone","email","internalNote"])if(key in payload)payload[key]="[withheld]";}return{...message,payload};});await db.prepare("INSERT INTO conversation_audit_events (id,thread_id,action,actor_email,detail_json,created_at) VALUES (?,?,?,?,?,?)").bind(uid("CONVAUD"),input.threadId,"transcript_exported",input.actorEmail,JSON.stringify({masked:input.maskSensitive}),Date.now()).run();return{thread:conversation.thread,messages,masked:input.maskSensitive,audited:true};}
